      ctx.rotate(angle + Math.PI / 2);
      ctx.fillStyle = colour;
      ctx.beginPath();
      ctx.ellipse(0, 0, radius + 6, radius - 4, 0, 0, TAU);
      ctx.fill();
    } else {
      ctx.rotate(angle);
      ctx.fillStyle = colour;
      ctx.beginPath();
      ctx.arc(0, 0, radius, 0, TAU);
      ctx.fill();
      ctx.fillStyle = 'rgba(0,0,0,0.35)';
      ctx.beginPath();
      ctx.arc(radius * 0.45, 0, radius * 0.55, 0, TAU);
      ctx.fill();
