    const spread = 0.42;
    ctx.save();
    ctx.translate(car.x, car.y);
    ctx.rotate(car.angle);
    const grad = ctx.createRadialGradient(0, 0, 10, 0, 0, range);
    grad.addColorStop(0, 'rgba(255,220,90,0.30)');
    grad.addColorStop(1, 'rgba(255,220,90,0)');
